package bowling

import "errors"

var (
	errNegativeRoll    = errors.New("Negative roll is invalid")
	errTooManyPins     = errors.New("Pin count exceeds pins on the lane")
	errGameAlreadyOver = errors.New("Cannot roll after game is over")
	errGameIncomplete  = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of the rolls in a game of bowling and can compute
// the total score once the game is complete.
type Game struct {
	rolls        []int // every roll that has been made
	frame        int   // index of the frame currently being played (0-9)
	rollInFrame  int   // number of rolls already made in the current frame
	firstRoll    int   // pins knocked down on the first roll of the current frame
	secondRoll   int   // pins knocked down on the second roll of the current frame
	gameOver     bool
}

func NewGame() *Game {
	return &Game{}
}

func (g *Game) Roll(pins int) error {
	if g.gameOver {
		return errGameAlreadyOver
	}
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}

	switch g.rollInFrame {
	case 0:
		// first roll of the frame: no extra constraint beyond 0-10
	case 1:
		// second roll: cannot exceed the pins left standing
		if g.firstRoll < 10 && pins > 10-g.firstRoll {
			return errTooManyPins
		}
		// if the first roll was a strike (in the 10th frame), any 0-10 is fine
	case 2:
		// third (bonus) roll, only possible in the 10th frame
		if g.secondRoll < 10 && pins > 10-g.secondRoll {
			return errTooManyPins
		}
	}

	g.rolls = append(g.rolls, pins)

	switch g.rollInFrame {
	case 0:
		g.firstRoll = pins
		g.rollInFrame = 1
		if pins == 10 && g.frame < 9 {
			// strike in a regular frame: frame complete
			g.advanceFrame()
		}
	case 1:
		g.secondRoll = pins
		g.rollInFrame = 2
		if g.frame < 9 {
			// regular frame: always complete after two rolls
			g.advanceFrame()
		} else {
			// 10th frame: decide whether a bonus roll is needed
			if g.firstRoll == 10 || g.firstRoll+g.secondRoll == 10 {
				// strike or spare: one bonus roll
				// (rollInFrame stays 2, waiting for the 3rd roll)
			} else {
				g.gameOver = true
			}
		}
	case 2:
		// bonus roll in the 10th frame
		g.gameOver = true
	}
	return nil
}

func (g *Game) advanceFrame() {
	g.frame++
	g.rollInFrame = 0
	g.firstRoll = 0
	g.secondRoll = 0
}
```

